package com.dpworld.fms.api;
import jakarta.servlet.*; import jakarta.servlet.http.*; import org.slf4j.MDC; import org.springframework.stereotype.Component; import java.io.IOException; import java.util.UUID;
@Component public class CorrelationIdFilter extends OncePerRequestFilter { private static final String HEADER="X-Correlation-ID"; protected void doFilterInternal(HttpServletRequest request,HttpServletResponse response,FilterChain chain)throws ServletException,IOException{var id=request.getHeader(HEADER);if(id==null||id.isBlank())id=UUID.randomUUID().toString();MDC.put("correlationId",id);response.setHeader(HEADER,id);try{chain.doFilter(request,response);}finally{MDC.remove("correlationId");}} private abstract static class OncePerRequestFilter extends org.springframework.web.filter.OncePerRequestFilter{} }
